    def constants(path):
        t = ast.parse(path.read_text(encoding='utf-8-sig'))
        return {n.targets[0].id: ast.literal_eval(n.value) for n in t.body if isinstance(n, ast.Assign) and isinstance(n.value, ast.Constant) and isinstance(n.value.value, str)}
